const DETAIL = {"respiratory":{"diagnosis":[{"topic":"慢阻肺","cells":["长期反复咳嗽、咳痰、气促；可有桶状胸、过清音","把慢性基础与本次加重诱因分开","临床诊断还需肺功能等依据，外观不能单独确诊"],"source":"D05:P0022–P0046","id":"respiratory-diagnosis-0"},{"topic":"支气管扩张","cells":["反复咳嗽、脓痰、咯血；可有杵状指","与肺炎、结核等咯血原因鉴别","影像支持，不能凭痰量一项定病名"],"source":"D05:P0022–P0046","id":"respiratory-diagnosis-1"},{"topic":"支气管哮喘","cells":["阵发性呼气困难、哮鸣音，夜间/凌晨可重，可能有诱因","关注可变性和气流受限","严重发作不因哮鸣音不明显就排除危险"],"source":"D05:P0022–P0046","id":"respiratory-diagnosis-2"},{"topic":"肺炎链球菌肺炎","cells":["寒战、高热、胸痛，可见铁锈色痰和实变影","典型组合用于考试识别","痰色不是病原学确证"],"source":"D05:P0022–P0046","id":"respiratory-diagnosis-3"},{"topic":"肺脓肿","cells":["高热、脓臭痰；影像可见空洞伴液平","结合误吸或感染来源","不能把所有空洞都当脓肿"],"source":"D05:P0022–P0046","id":"respiratory-diagnosis-4"},{"topic":"肺结核","cells":["咳嗽、咯血伴低热、盗汗、消瘦等","结合病原与影像评估","典型体征缺如不排除"],"source":"D05:P0022–P0046","id":"respiratory-diagnosis-5"},{"topic":"自发性气胸","cells":["突发胸痛、气促加重，患侧呼吸音减弱","在慢性肺病突然恶化时重评","严重通气或循环异常优先急救"],"source":"D05:P0022–P0046","id":"respiratory-diagnosis-6"},{"topic":"肺心病","cells":["肺病背景＋下肢水肿、颈静脉充盈等右心表现","结合心电、影像和心功能","水肿也可能有其他原因"],"source":"D05:P0022–P0046","id":"respiratory-diagnosis-7"}],"labs":[{"topic":"Ⅰ型呼衰口径","cells":["讲义：PaO₂＜60 mmHg，PaCO₂不升高","以低氧为主，结合临床和血气","需注明静息、海平面、室内空气等判定条件"],"source":"D05:P0039–P0057","id":"respiratory-labs-0"},{"topic":"Ⅱ型呼衰口径","cells":["讲义：PaO₂＜60 mmHg且PaCO₂＞50 mmHg","低氧合并通气不足方向","不能按慢阻肺病名自动分型"],"source":"D05:P0039–P0057","id":"respiratory-labs-1"},{"topic":"血气pH、PaCO₂、HCO₃⁻","cells":["联合观察变化与代偿","区分通气与代谢问题","单看CO₂不能完成酸碱分析"],"source":"D05:P0039–P0057","id":"respiratory-labs-2"},{"topic":"血常规、CRP、PCT","cells":["炎症相关信息","辅助判断感染与严重程度","不能单项确定病原或决定全部治疗"],"source":"D05:P0039–P0057","id":"respiratory-labs-3"},{"topic":"痰培养与涂片","cells":["有感染/病原学问题时选取标本","帮助病原判断及治疗选择","留取质量、既往用药会影响解释"],"source":"D05:P0039–P0057","id":"respiratory-labs-4"},{"topic":"胸片/胸部CT","cells":["显示实变、支扩、空洞、积气等","定位病变和并发症","影像词与具体检查方式要匹配"],"source":"D05:P0039–P0057","id":"respiratory-labs-5"},{"topic":"肺功能与支气管试验","cells":["气流受限及其可变性","支持慢阻肺/哮喘鉴别","急性不稳定时先评估能否进行"],"source":"D05:P0039–P0057","id":"respiratory-labs-6"}],"treatment":[{"topic":"支气管舒张治疗","cells":["按病情选用相关药物","降低气道阻力，观察症状与不良反应","制剂、使用方式和治疗阶段不同"],"source":"D05:P0090–P0104、P0113–P0125","id":"respiratory-treatment-0"},{"topic":"抗感染治疗","cells":["感染证据、病原及临床状态共同指导","观察体温、痰液、炎症与耐受","不把所有咳痰都等同细菌感染"],"source":"D05:P0090–P0104、P0113–P0125","id":"respiratory-treatment-1"},{"topic":"排痰支持","cells":["有效咳嗽、必要的气道湿化/清除措施","改善清除能力，评价通畅程度","咯血、意识障碍等需重新评估方法"],"source":"D05:P0090–P0104、P0113–P0125","id":"respiratory-treatment-2"},{"topic":"氧疗与通气支持","cells":["按目标氧合、血气和呼吸功调整","纠正低氧，必要时升级支持","讲义固定流量不作为全部患者通则"],"source":"D05:P0090–P0104、P0113–P0125","id":"respiratory-treatment-3"}],"nursing":[{"topic":"清理呼吸道无效","cells":["与分泌物黏稠、增多或咳嗽无力有关","观察痰色、性质、量及排出能力，协助排痰","不能只写“气道通畅”而无具体动作"],"source":"D05:P0062–P0064、P0078–P0089、P0100–P0127","id":"respiratory-nursing-0"},{"topic":"气体交换受损","cells":["与肺部病变影响氧合/通气有关","监测呼吸、血氧、血气与意识，观察治疗反应","具体因素按题干，不照搬所有病因"],"source":"D05:P0062–P0064、P0078–P0089、P0100–P0127","id":"respiratory-nursing-1"},{"topic":"活动无耐力","cells":["活动时气促、心悸、疲劳等证据","稳定后分阶段活动，出现不耐受停止并评估","急性危险未解决先不推进训练"],"source":"D05:P0062–P0064、P0078–P0089、P0100–P0127","id":"respiratory-nursing-2"},{"topic":"咯血观察","cells":["记录量、频次、血液能否排出及意识","防气道堵塞，及时报告窒息/循环异常","大量咯血不能机械套普通叩背排痰"],"source":"D05:P0062–P0064、P0078–P0089、P0100–P0127","id":"respiratory-nursing-3"},{"topic":"肺性脑病警讯","cells":["昼夜节律改变、嗜睡、意识变化等","复评血气及通气，做好安全与气道护理","同时排查低血糖、药物等其他原因"],"source":"D05:P0062–P0064、P0078–P0089、P0100–P0127","id":"respiratory-nursing-4"},{"topic":"饮食与水分","cells":["足够营养，饮水可帮助痰液处理","按吞咽、呼吸状态和心肾功能选择途径","不统一要求大量饮水或固定限水"],"source":"D05:P0062–P0064、P0078–P0089、P0100–P0127","id":"respiratory-nursing-5"}]},"cardiac":{"diagnosis":[{"topic":"左心衰","cells":["呼吸困难、肺部湿啰音，可有奔马律","反映肺淤血与泵功能问题","需与肺部病变等鉴别"],"source":"D06:P0007–P0033","id":"cardiac-diagnosis-0"},{"topic":"右心衰","cells":["水肿、颈静脉充盈、肝大及腹部不适","反映体循环淤血方向","不把所有下肢水肿归因心衰"],"source":"D06:P0007–P0033","id":"cardiac-diagnosis-1"},{"topic":"急性肺水肿","cells":["突发严重气促、端坐、粉红色泡沫痰","优先评估呼吸与循环","血压变化会影响体位和治疗"],"source":"D06:P0007–P0033","id":"cardiac-diagnosis-2"},{"topic":"心绞痛与心肌梗死","cells":["前者典型为短暂诱发性胸痛；后者常持续且难缓解","结合心电与心肌损伤标志物","单凭疼痛持续时间或含药反应不能排除心梗"],"source":"D06:P0007–P0033","id":"cardiac-diagnosis-3"},{"topic":"房颤","cells":["节律绝对不齐、脉搏短绌，心电可见f波","结合心率、灌注及栓塞风险","不能只触脉确诊或自行抗凝"],"source":"D06:P0007–P0033","id":"cardiac-diagnosis-4"},{"topic":"心包压塞方向","cells":["低血压、心音低弱、颈静脉充盈的组合","结合超声与循环状态","缺少完整三联征也可能需要紧急评估"],"source":"D06:P0007–P0033","id":"cardiac-diagnosis-5"}],"labs":[{"topic":"心电图","cells":["心率、节律、ST-T及传导变化","心律失常和缺血评估","症状持续时可能需要动态/复查"],"source":"D06:P0034–P0047","id":"cardiac-labs-0"},{"topic":"肌钙蛋白","cells":["心肌损伤标志物及其动态升降","结合临床判断心肌梗死等","升高不只见于冠脉血栓性心梗"],"source":"D06:P0034–P0047","id":"cardiac-labs-1"},{"topic":"BNP/NT-proBNP","cells":["心室负荷相关指标","辅助心衰判断与评估","结合年龄、肾功能等因素"],"source":"D06:P0034–P0047","id":"cardiac-labs-2"},{"topic":"超声心动图","cells":["心腔、瓣膜、收缩功能及LVEF等","评估结构和功能","不能用一个舒张参数独立定性"],"source":"D06:P0034–P0047","id":"cardiac-labs-3"},{"topic":"电解质与肾功能","cells":["钾、钠、肌酐等变化","心律风险及治疗耐受","利尿、RAAS相关药等用药后需关注"],"source":"D06:P0034–P0047","id":"cardiac-labs-4"},{"topic":"冠脉造影","cells":["冠脉病变部位及程度","诊断与介入治疗评估","检查适应证与风险由专业评估"],"source":"D06:P0034–P0047","id":"cardiac-labs-5"}],"treatment":[{"topic":"急性心衰支持","cells":["低氧时氧疗，必要时通气支持；按情况利尿、扩血管等","缓解淤血并维护灌注","不把吗啡和酒精湿化列为人人必用"],"source":"D06:P0068–P0081、P0117–P0137","id":"cardiac-treatment-0"},{"topic":"缺血/心梗处理","cells":["抗栓和再灌注等按诊断与时机选择","恢复灌注并控制并发症","不能把溶栓用于全部胸痛"],"source":"D06:P0068–P0081、P0117–P0137","id":"cardiac-treatment-1"},{"topic":"慢性心衰药物框架","cells":["讲义列RAAS相关药、β阻滞剂、MRA和SGLT2类","长期管理与预后改善方向","不将ACEI与ARB同时列成必用组合"],"source":"D06:P0068–P0081、P0117–P0137","id":"cardiac-treatment-2"},{"topic":"利尿治疗监测","cells":["尿量、体重、血压、电解质和肾功能","观察去淤血效果及容量不足","不以尿越多越好作为目标"],"source":"D06:P0068–P0081、P0117–P0137","id":"cardiac-treatment-3"},{"topic":"恶性心律异常","cells":["配合监护与专业急救处置","预防循环崩溃及猝死","具体药物/电复律不作自主指令"],"source":"D06:P0068–P0081、P0117–P0137","id":"cardiac-treatment-4"}],"nursing":[{"topic":"体位","cells":["呼吸困难时依耐受采取有利体位","观察血压、呼吸与舒适程度","低血压时不能继续套端坐垂腿"],"source":"D06:P0051–P0067、P0082–P0086、P0110–P0145","id":"cardiac-nursing-0"},{"topic":"容量记录","cells":["同条件测体重，记录出入量及水肿","联系呼吸、尿量与治疗反应","不能单靠一天体重决定给药"],"source":"D06:P0051–P0067、P0082–P0086、P0110–P0145","id":"cardiac-nursing-1"},{"topic":"胸痛记录","cells":["部位、性质、强度、起止、诱因及伴随表现","及时报告持续或恶化胸痛","不因疼痛减轻而停止必要评估"],"source":"D06:P0051–P0067、P0082–P0086、P0110–P0145","id":"cardiac-nursing-2"},{"topic":"活动康复","cells":["从病情允许的生活活动递进","监测气促、心悸、头晕、血压心律","出现不耐受停止并复评"],"source":"D06:P0051–P0067、P0082–P0086、P0110–P0145","id":"cardiac-nursing-3"},{"topic":"用药安全","cells":["观察降压后体位性症状、利尿后电解质变化","指导按医嘱，不自行停药","用药差异不能一套宣教"],"source":"D06:P0051–P0067、P0082–P0086、P0110–P0145","id":"cardiac-nursing-4"},{"topic":"出院自测","cells":["体重、血压、心率及水肿/气促变化","识别复发并及时就医","抗凝者另关注出血线索"],"source":"D06:P0051–P0067、P0082–P0086、P0110–P0145","id":"cardiac-nursing-5"}]},"diabetes":{"diagnosis":[{"topic":"糖尿病诊断数值","cells":["讲义列FPG≥7.0 mmol/L、随机或OGTT 2h≥11.1 mmol/L","与典型症状、检验方法及复核要求结合","无典型症状不能随意用一次值确诊"],"source":"D03:P0004–P0012","id":"diabetes-diagnosis-0"},{"topic":"1型线索","cells":["年轻、起病较急、消瘦、酮症及自身抗体","区分胰岛素缺乏背景","年龄不能单独分型"],"source":"D03:P0004–P0012","id":"diabetes-diagnosis-1"},{"topic":"2型线索","cells":["隐匿起病、超重/家族史及胰岛素抵抗","综合病史与检查分型","不能简单理解为永远不用胰岛素"],"source":"D03:P0004–P0012","id":"diabetes-diagnosis-2"},{"topic":"DKA","cells":["糖尿病/相关背景＋酮体升高＋代谢性酸中毒","深快呼吸、恶心、腹痛、脱水提供线索","存在血糖不高的DKA，SGLT2背景尤其注意"],"source":"D03:P0004–P0012","id":"diabetes-diagnosis-3"},{"topic":"高渗状态","cells":["显著高血糖、高渗、脱水和神经症状","与DKA和其他昏迷原因鉴别","可有重叠，不能仅凭年龄分类"],"source":"D03:P0004–P0012","id":"diabetes-diagnosis-4"},{"topic":"低血糖","cells":["出汗、手抖、饥饿、心慌或意识异常，血糖降低","联系进餐、活动及降糖药","严重程度还要看是否需他人帮助"],"source":"D03:P0004–P0012","id":"diabetes-diagnosis-5"},{"topic":"糖尿病足","cells":["神经病变、血供障碍、感染/溃疡等","区分感觉、缺血与感染问题","有伤口不能仅当皮肤清洁问题"],"source":"D03:P0004–P0012","id":"diabetes-diagnosis-6"}],"labs":[{"topic":"即时血糖","cells":["反映采样时血糖","识别高/低血糖并追踪治疗","写清空腹、餐后、随机及单位"],"source":"D03:P0013–P0033","id":"diabetes-labs-0"},{"topic":"HbA1c","cells":["讲义：主要反映近2–3个月平均水平","长期控制评估","不能取代此刻血糖或单独解释急症"],"source":"D03:P0013–P0033","id":"diabetes-labs-1"},{"topic":"血酮","cells":["酮体增多支持酮症评估","与酸碱共同判断DKA","尿酮与血酮不能简单互代"],"source":"D03:P0013–P0033","id":"diabetes-labs-2"},{"topic":"血气与碳酸氢根","cells":["pH、HCO₃⁻及呼吸代偿","确认和追踪酸中毒","原讲义固定高糖范围不能做排除条件"],"source":"D03:P0013–P0033","id":"diabetes-labs-3"},{"topic":"血钾","cells":["初期可不低，但总体可缺钾","治疗过程动态监测","胰岛素/补液后变化需警惕"],"source":"D03:P0013–P0033","id":"diabetes-labs-4"},{"topic":"渗透压与肾功能","cells":["高渗、脱水及排泄能力","评估高渗状态和治疗耐受","实际计算需确认单位和公式"],"source":"D03:P0013–P0033","id":"diabetes-labs-5"},{"topic":"足部感觉与血供","cells":["保护性感觉测试、足动脉、必要时踝肱指数","分层判断足溃疡/缺血风险","数值受血管钙化等影响，结合专业评估"],"source":"D03:P0013–P0033","id":"diabetes-labs-6"}],"treatment":[{"topic":"清醒低血糖","cells":["能安全吞咽时按流程经口补糖；讲义有15–20g、15分钟复测口径","纠正后复测，并评估下一餐与复发","意识或吞咽障碍时不可强行喂食"],"source":"D03:P0064–P0090","id":"diabetes-treatment-0"},{"topic":"严重低血糖","cells":["非经口纠正按急救流程和医嘱","保护气道并观察恢复","讲义静脉高浓度剂量不作通用自助方案"],"source":"D03:P0064–P0090","id":"diabetes-treatment-1"},{"topic":"DKA支持","cells":["补液、胰岛素、电解质处理及诱因控制协同","终点不只看血糖，还看酮症/酸中毒纠正","原讲义固定速度及停胰岛素口径待核对"],"source":"D03:P0064–P0090","id":"diabetes-treatment-2"},{"topic":"胰岛素使用","cells":["核对制剂、剂量、时间与进餐","监测低血糖及注射部位变化","不同制剂不可按一个时程用"],"source":"D03:P0064–P0090","id":"diabetes-treatment-3"},{"topic":"足部治疗","cells":["感染评估、合适敷料和必要的血供/减压处理","控制感染、保护创面并减少承重损伤","不是所有伤口都只需自行换药"],"source":"D03:P0064–P0090","id":"diabetes-treatment-4"}],"nursing":[{"topic":"低血糖复发预防","cells":["记录药物、进餐和运动诱因，教会识别预警","携带应急用品并按方案复测","不让症状缓解代替复测"],"source":"D03:P0041–P0073、P0091–P0111","id":"diabetes-nursing-0"},{"topic":"胰岛素注射部位","cells":["观察硬结及脂肪改变，按方案轮换","避免长期在同一点反复注射","储存温度、开封期限按具体制剂"],"source":"D03:P0041–P0073、P0091–P0111","id":"diabetes-nursing-1"},{"topic":"饮食组织","cells":["总能量个体化，定时定量与药物/活动配合","复评体重、血糖和摄入","肾病、妊娠、消瘦等需调整"],"source":"D03:P0041–P0073、P0091–P0111","id":"diabetes-nursing-2"},{"topic":"糖尿病足观察","cells":["每日看皮温肤色、感觉、趾间和鞋内异物","合适鞋袜，预防烫伤、外伤和修甲损伤","缺血足不统一抬高或热敷"],"source":"D03:P0041–P0073、P0091–P0111","id":"diabetes-nursing-3"},{"topic":"生病日管理","cells":["感染、发热、腹泻时监测并联系专业人员调整","避免擅停关键治疗","尤其不能把DKA高风险期当普通休息即可"],"source":"D03:P0041–P0073、P0091–P0111","id":"diabetes-nursing-4"},{"topic":"五方面教育","cells":["饮食、活动、药物、监测与疾病教育","让患者能演示记录和处理方式","不是只背“五驾马车”名称"],"source":"D03:P0041–P0073、P0091–P0111","id":"diabetes-nursing-5"}]},"thyroid":{"diagnosis":[{"topic":"Graves/甲亢线索","cells":["怕热多汗、多食消瘦、心悸及甲状腺/眼部表现","结合甲功和病因评估","症状不等于所有甲亢都为Graves"],"source":"D01:P0003–P0004、P0042–P0043、P0089–P0115","id":"thyroid-diagnosis-0"},{"topic":"甲状腺恶性结节线索","cells":["质硬固定结节、压迫表现、可疑淋巴结或超声征","进一步分层及取样","触诊不能独立确诊癌"],"source":"D01:P0003–P0004、P0042–P0043、P0089–P0115","id":"thyroid-diagnosis-1"},{"topic":"甲状腺危象","cells":["高热、显著心动过速、意识及胃肠症状等恶化","手术、感染、停药等可为诱因","按整体临床评估，不等齐所有阈值"],"source":"D01:P0003–P0004、P0042–P0043、P0089–P0115","id":"thyroid-diagnosis-2"},{"topic":"术后呼吸困难","cells":["可能为血肿压迫、喉头水肿、气管问题或双侧神经损伤","优先气道评估和急救配合","不能仅归因切口疼痛"],"source":"D01:P0003–P0004、P0042–P0043、P0089–P0115","id":"thyroid-diagnosis-3"},{"topic":"喉返/喉上神经损伤","cells":["声嘶/发声异常；饮水呛咳或误咽","分别看发声与吞咽安全","具体损伤部位需专业判断"],"source":"D01:P0003–P0004、P0042–P0043、P0089–P0115","id":"thyroid-diagnosis-4"},{"topic":"甲旁腺功能下降","cells":["口周/肢端麻木、痉挛抽搐","结合钙代谢评估","严重时也可威胁呼吸"],"source":"D01:P0003–P0004、P0042–P0043、P0089–P0115","id":"thyroid-diagnosis-5"}],"labs":[{"topic":"TSH、FT3、FT4","cells":["典型原发甲亢常见TSH抑制、游离激素升高","功能判断","结合病程、药物与不同疾病类型"],"source":"D01:P0005–P0025、P0104–P0109","id":"thyroid-labs-0"},{"topic":"TRAb等抗体","cells":["有助Graves病因判断","不只回答有没有甲亢","抗体结果需与甲功临床联合"],"source":"D01:P0005–P0025、P0104–P0109","id":"thyroid-labs-1"},{"topic":"甲状腺超声","cells":["弥漫性改变、血流；结节边界、回声、钙化等","结构及风险评估","可疑征不等于病理确诊"],"source":"D01:P0005–P0025、P0104–P0109","id":"thyroid-labs-2"},{"topic":"细针取样","cells":["细胞学帮助结节良恶性判断","术前风险分类","部分类型仍需组织病理与进一步评估"],"source":"D01:P0005–P0025、P0104–P0109","id":"thyroid-labs-3"},{"topic":"降钙素","cells":["与髓样癌评估有关","亚型线索和随访用途","不是所有甲状腺癌都会升高"],"source":"D01:P0005–P0025、P0104–P0109","id":"thyroid-labs-4"},{"topic":"钙水平","cells":["术后抽搐/麻木时关注","支持低钙及治疗监测","不能不查病因就统一补钙"],"source":"D01:P0005–P0025、P0104–P0109","id":"thyroid-labs-5"}],"treatment":[{"topic":"甲亢药物治疗","cells":["抗甲状腺药等控制甲状腺激素相关状态","观察血象、肝功能和症状","发热/咽痛等需及时联系专业人员"],"source":"D01:P0029–P0039、P0060–P0088、P0091–P0109","id":"thyroid-treatment-0"},{"topic":"术前准备","cells":["控制甲亢状态并完成必要评估和训练","降低围术期风险","用药顺序和时间服从具体方案"],"source":"D01:P0029–P0039、P0060–P0088、P0091–P0109","id":"thyroid-treatment-1"},{"topic":"危象处理","cells":["气道循环支持、降温及针对激素相关治疗","及时急救配合和监测","不沿用讲义统一补液量或镇静药"],"source":"D01:P0029–P0039、P0060–P0088、P0091–P0109","id":"thyroid-treatment-2"},{"topic":"术后血肿压迫","cells":["及时呼叫支援并准备配合解除压迫/气道处理","呼吸危险优先","侵入操作由有资质团队执行"],"source":"D01:P0029–P0039、P0060–P0088、P0091–P0109","id":"thyroid-treatment-3"},{"topic":"低钙处理","cells":["按钙水平、症状与医嘱补充及监测","缓解神经肌肉症状","具体制剂、速度及饮食要个体化"],"source":"D01:P0029–P0039、P0060–P0088、P0091–P0109","id":"thyroid-treatment-4"}],"nursing":[{"topic":"眼部防护","cells":["减少风沙强光刺激，观察眼睑闭合及角膜干燥","依眼部方案保湿保护","不自行揉搓或套用激素眼药"],"source":"D01:P0044–P0065、P0083–P0115","id":"thyroid-nursing-0"},{"topic":"药物不良反应","cells":["抗甲状腺药关注粒细胞及肝脏问题","解释异常症状与复查","停药/换药由医嘱指导"],"source":"D01:P0044–P0065、P0083–P0115","id":"thyroid-nursing-1"},{"topic":"颈部术后观察","cells":["颈围肿胀、敷料渗血、引流、声音及呼吸","出现紧绷和气促立即报告","不等血氧显著下降才处理"],"source":"D01:P0044–P0065、P0083–P0115","id":"thyroid-nursing-2"},{"topic":"吞咽护理","cells":["呛咳/误咽者先评估，再安排食物性状和途径","防误吸并维护营养","清醒并不保证吞咽安全"],"source":"D01:P0044–P0065、P0083–P0115","id":"thyroid-nursing-3"},{"topic":"乳糜漏方向","cells":["乳白/淡粉引流且进食后变化","配合评估、引流、营养与皮肤保护","颜色不能单独定诊断"],"source":"D01:P0044–P0065、P0083–P0115","id":"thyroid-nursing-4"}]},"renal":{"diagnosis":[{"topic":"急性肾小球肾炎","cells":["感染后背景＋血尿、水肿、高血压，C3可降低","肾炎综合征方向","要记录感染与起病间隔"],"source":"D07:P0004–P0013","id":"renal-diagnosis-0"},{"topic":"急进性肾炎","cells":["肾炎表现伴肾功能迅速下降和少尿/无尿","可能需活检等进一步判断","不是只按肌酐高低区分"],"source":"D07:P0004–P0013","id":"renal-diagnosis-1"},{"topic":"肾病综合征","cells":["讲义：尿蛋白＞3.5g/d、白蛋白＜30g/L，常伴水肿、高脂","大量蛋白丢失相关组合","数值适用成人口径；需排病因"],"source":"D07:P0004–P0013","id":"renal-diagnosis-2"},{"topic":"膀胱炎与肾盂肾炎","cells":["前者以尿频急痛为主；后者常有发热寒战、腰痛/肾区叩痛","区分下尿路与上尿路感染方向","老年或特殊人群可不典型"],"source":"D07:P0004–P0013","id":"renal-diagnosis-3"},{"topic":"AKI","cells":["讲义：48h肌酐增≥26.5μmol/L，或7d达基线≥1.5倍，或少尿标准","需基线、时段和体重","讲义尿量写＜0.5ml/(kg·h)持续约6h，须按适用标准核对"],"source":"D07:P0004–P0013","id":"renal-diagnosis-4"},{"topic":"慢性肾脏病方向","cells":["长期肾脏异常，肾功能/蛋白尿等持续","慢性背景与急性加重分开","不能凭一次eGFR或双肾大小独断"],"source":"D07:P0004–P0013","id":"renal-diagnosis-5"}],"labs":[{"topic":"尿常规","cells":["蛋白、红细胞、白细胞和管型等","区分肾实质、出血及感染线索","标本污染会影响解释"],"source":"D07:P0064–P0081、P0090–P0105","id":"renal-labs-0"},{"topic":"24h尿蛋白","cells":["讲义＞150mg/d为蛋白尿口径；成人大量蛋白尿＞3.5g/d","评估蛋白丢失程度","D07:P0068单位有误，不照抄“m³”"],"source":"D07:P0064–P0081、P0090–P0105","id":"renal-labs-1"},{"topic":"白蛋白与血脂","cells":["低白蛋白、高脂血症可见于肾病综合征","联合蛋白尿解释水肿","低白蛋白还有营养、肝病等原因"],"source":"D07:P0064–P0081、P0090–P0105","id":"renal-labs-2"},{"topic":"Scr、BUN、eGFR","cells":["肾排泄/滤过评估及变化","与基线、趋势和容量结合","BUN受出血、摄入等影响，非特异"],"source":"D07:P0064–P0081、P0090–P0105","id":"renal-labs-3"},{"topic":"尿培养","cells":["合适尿标本培养及药敏","尿路感染病原与治疗参考","原讲义CFU/ml与高倍镜混写，不作显微计数阈值"],"source":"D07:P0064–P0081、P0090–P0105","id":"renal-labs-4"},{"topic":"血钾＋心电图","cells":["可见高尖T波、传导变化等","判断电解质相关风险","没有典型心电改变不排除高钾"],"source":"D07:P0064–P0081、P0090–P0105","id":"renal-labs-5"},{"topic":"超声/肾活检","cells":["结构、梗阻线索；活检可明确部分病理类型","影像与病理各有适应证","不是所有肾病都必须活检"],"source":"D07:P0064–P0081、P0090–P0105","id":"renal-labs-6"}],"treatment":[{"topic":"高钾：保护心肌","cells":["静脉钙剂等用于相应紧急情况","稳定心肌电活动","并非直接把体内钾排掉，按医嘱监测"],"source":"D07:P0106–P0131","id":"renal-treatment-0"},{"topic":"高钾：转移钾","cells":["胰岛素与葡萄糖等，碱剂按适用条件","使钾向细胞内转移","需防低血糖和反跳，不是最终清除"],"source":"D07:P0106–P0131","id":"renal-treatment-1"},{"topic":"高钾：清除钾","cells":["按情况选择药物或透析","减少体内钾负荷","具体方式取决肾功能、严重程度等"],"source":"D07:P0106–P0131","id":"renal-treatment-2"},{"topic":"替代治疗方向","cells":["严重高钾、难纠酸中毒/肺水肿、严重尿毒症等","专业评估透析需要","不只以单一肌酐或阈值决定"],"source":"D07:P0106–P0131","id":"renal-treatment-3"},{"topic":"激素/免疫抑制","cells":["部分肾小球病按病理与方案使用","控制病因及蛋白尿等","感染、血糖、骨骼和脏器风险需观察"],"source":"D07:P0106–P0131","id":"renal-treatment-4"},{"topic":"利尿/降压","cells":["按容量和血压等安排","复评尿量、血压、电解质和肾功能","RAAS相关药可能影响钾/肌酐，不自行加减"],"source":"D07:P0106–P0131","id":"renal-treatment-5"}],"nursing":[{"topic":"体液过多","cells":["水肿、体重、出入量、呼吸及血压同看","同条件测量，动态评价治疗","不能所有人统一“前日尿量＋固定量”"],"source":"D07:P0083–P0096、P0119–P0171","id":"renal-nursing-0"},{"topic":"水肿皮肤","cells":["看受压、渗液、瘙痒和完整性","减少抓挠损伤，避免不必要水肿处穿刺","有灌注异常时体位另评估"],"source":"D07:P0083–P0096、P0119–P0171","id":"renal-nursing-1"},{"topic":"营养","cells":["热量、蛋白、水钠、钾磷按病程安排","结合营养状态、透析与检查","非透析与透析蛋白需求不可混写"],"source":"D07:P0083–P0096、P0119–P0171","id":"renal-nursing-2"},{"topic":"感染预防","cells":["口腔、皮肤、环境和导管无菌维护","观察发热与局部感染灶","免疫抑制者需特别评估"],"source":"D07:P0083–P0096、P0119–P0171","id":"renal-nursing-3"},{"topic":"内瘘保护","cells":["内瘘侧避测压、穿刺和受压，保持清洁","按培训检查震颤/杂音变化","异常联系透析团队，不自行揉压"],"source":"D07:P0083–P0096、P0119–P0171","id":"renal-nursing-4"},{"topic":"高钾护理","cells":["连续观察心律、生命体征、血钾与用药反应","及时报告异常并准备配合处理","治疗中也需关注低血糖和电解质反向变化"],"source":"D07:P0083–P0096、P0119–P0171","id":"renal-nursing-5"}]},"digestive":{"diagnosis":[{"topic":"胃/十二指肠溃疡","cells":["讲义：胃溃疡多餐后痛；十二指肠多延迟、饥饿或夜间痛","典型节律用于对照","临床疼痛规律并非必然，需内镜等"],"source":"D09:P0043–P0055、D22:P0022–P0039","id":"digestive-diagnosis-0"},{"topic":"穿孔","cells":["突发剧痛向全腹扩展，腹膜刺激、可见膈下游离气","急腹症与穿孔方向","无游离气不排除"],"source":"D09:P0043–P0055、D22:P0022–P0039","id":"digestive-diagnosis-1"},{"topic":"幽门梗阻","cells":["反复呕宿食、胃潴留、振水音等","关注脱水及酸碱紊乱","不把所有术后呕吐都当幽门梗阻"],"source":"D09:P0043–P0055、D22:P0022–P0039","id":"digestive-diagnosis-2"},{"topic":"上消化道出血","cells":["呕血、黑便及头晕、冷汗、低灌注","先评估失血严重度再查病因","黑便持续不独立证明还在活动性大出血"],"source":"D09:P0043–P0055、D22:P0022–P0039","id":"digestive-diagnosis-3"},{"topic":"肝硬化","cells":["肝功能减退与门脉高压表现：腹水、脾大等","组合判断失代偿及并发症","不能只凭蜘蛛痣定诊断"],"source":"D09:P0043–P0055、D22:P0022–P0039","id":"digestive-diagnosis-4"},{"topic":"肝性脑病","cells":["肝病背景、认知/行为/意识变化，可有扑翼样震颤","寻找感染、出血、便秘、药物诱因","血氨不是单独确诊和分级工具"],"source":"D09:P0043–P0055、D22:P0022–P0039","id":"digestive-diagnosis-5"},{"topic":"急性胰腺炎","cells":["上腹痛向背放射、酶学升高、影像异常组合","常按症状、酶学、影像三方面评估","单一高淀粉酶不等于胰腺炎"],"source":"D09:P0043–P0055、D22:P0022–P0039","id":"digestive-diagnosis-6"}],"labs":[{"topic":"血常规与凝血","cells":["Hb、血细胞和凝血变化","出血、肝病及治疗评估","急性失血早期Hb可尚未明显下降"],"source":"D09:P0056–P0070","id":"digestive-labs-0"},{"topic":"肝肾功能、电解质、血氨","cells":["肝病代谢与器官影响","结合症状及诱因分析","不把检验异常独立当病因"],"source":"D09:P0056–P0070","id":"digestive-labs-1"},{"topic":"淀粉酶/脂肪酶","cells":["讲义酶学明显升高可支持胰腺炎","与疼痛及影像联合","结果受时相影响，不能只看一次"],"source":"D09:P0056–P0070","id":"digestive-labs-2"},{"topic":"胃镜＋必要活检","cells":["出血部位、溃疡和肿瘤等","诊断并可行部分治疗","急症时机服从复苏和风险"],"source":"D09:P0056–P0070","id":"digestive-labs-3"},{"topic":"Hp检测","cells":["尿素呼气试验或内镜取样相关检测","消化性溃疡病因评估","用药/检查准备影响结果"],"source":"D09:P0056–P0070","id":"digestive-labs-4"},{"topic":"肠镜＋活检","cells":["炎症性肠病、肿瘤等","部位、性质和病理","急性重症或穿孔风险先评估"],"source":"D09:P0056–P0070","id":"digestive-labs-5"},{"topic":"腹部超声/CT","cells":["肝胆胰结构、积液和急腹症线索","帮助病因和并发症判断","检查准备按项目而非统一禁食时间"],"source":"D09:P0056–P0070","id":"digestive-labs-6"}],"treatment":[{"topic":"消化道出血","cells":["复苏、止血与病因治疗；可配合内镜等","维持灌注并控制失血","药物路径取决溃疡/静脉曲张等病因"],"source":"D09:P0094–P0117、P0127–P0135","id":"digestive-treatment-0"},{"topic":"肝硬化腹水","cells":["按情况利尿、营养和其他治疗","复评体重、尿量、钠钾和肾功能","过快去液可致有效循环不足"],"source":"D09:P0094–P0117、P0127–P0135","id":"digestive-treatment-1"},{"topic":"肝性脑病","cells":["处理诱因，按医嘱使用降氨相关治疗等","观察认知、排便和全身状态","不统一长期禁蛋白或常规镇静"],"source":"D09:P0094–P0117、P0127–P0135","id":"digestive-treatment-2"},{"topic":"急性胰腺炎","cells":["支持、镇痛、营养及病因处理","观察循环、脏器、疼痛和摄入","不以固定禁食天数覆盖所有病情"],"source":"D09:P0094–P0117、P0127–P0135","id":"digestive-treatment-3"},{"topic":"Hp相关溃疡","cells":["抑酸、根除感染和黏膜保护等","依方案复查与依从性管理","不自行拼药或按症状好转停疗程"],"source":"D09:P0094–P0117、P0127–P0135","id":"digestive-treatment-4"}],"nursing":[{"topic":"出血急性期","cells":["记录血量、血色、意识、皮温、血压和尿量","防误吸，配合通路与治疗","不能只量便血不看循环"],"source":"D09:P0073–P0093、P0118–P0144","id":"digestive-nursing-0"},{"topic":"腹水记录","cells":["同条件体重、腹围、出入量和水肿","观察呼吸、低钠及肾功能变化","统一限水/盐数值不适用于所有人"],"source":"D09:P0073–P0093、P0118–P0144","id":"digestive-nursing-1"},{"topic":"肝性脑病早期","cells":["观察睡眠、性格、行为和认知变化","及早发现诱因并报告","不要等到昏迷才记录"],"source":"D09:P0073–P0093、P0118–P0144","id":"digestive-nursing-2"},{"topic":"腹痛与引流","cells":["性质、部位、程度、放射及呕吐/减压液","联系穿孔、梗阻、胰腺等方向","镇痛后缓解不替代继续观察"],"source":"D09:P0073–P0093、P0118–P0144","id":"digestive-nursing-3"},{"topic":"营养与吞咽","cells":["选择途径、性状和分餐，结合禁食条件","保护摄入、减少误吸和再损伤","蛋白/水钠要随肝肾及阶段调整"],"source":"D09:P0073–P0093、P0118–P0144","id":"digestive-nursing-4"},{"topic":"黄疸瘙痒","cells":["温和清洁，宽松衣物，避免抓破","监测皮肤和感染","具体药物按医嘱"],"source":"D09:P0073–P0093、P0118–P0144","id":"digestive-nursing-5"}]},"neuro":{"diagnosis":[{"topic":"脑出血与脑梗死","cells":["均可突发局灶缺损；头痛呕吐、意识变化等提供线索","靠影像分型","不能仅按活动/安静起病确诊"],"source":"D10:P0008–P0028、P0079–P0118","id":"neuro-diagnosis-0"},{"topic":"蛛网膜下腔出血","cells":["雷击样剧烈头痛、呕吐、脑膜刺激表现","紧急评估出血原因","不能把年轻或无偏瘫作为排除条件"],"source":"D10:P0008–P0028、P0079–P0118","id":"neuro-diagnosis-1"},{"topic":"硬膜外血肿","cells":["外伤后可出现中间清醒再恶化","结合CT与瞳孔/肢体表现","没有典型中间清醒期也不能排除"],"source":"D10:P0008–P0028、P0079–P0118","id":"neuro-diagnosis-2"},{"topic":"急性硬膜下血肿","cells":["持续或进行性意识障碍","警惕伴脑挫裂伤","慢性型可在轻微伤后缓慢出现症状"],"source":"D10:P0008–P0028、P0079–P0118","id":"neuro-diagnosis-3"},{"topic":"颅底骨折","cells":["前窝可熊猫眼/鼻漏；中窝可耳漏、乳突区瘀斑","结合影像和神经表现","不能用一个外观征确诊漏液"],"source":"D10:P0008–P0028、P0079–P0118","id":"neuro-diagnosis-4"},{"topic":"小脑幕切迹疝","cells":["意识恶化、瞳孔变化与对侧肢体障碍等","立即升级急救","并非每例都按固定顺序发展"],"source":"D10:P0008–P0028、P0079–P0118","id":"neuro-diagnosis-5"},{"topic":"枕骨大孔疝","cells":["呼吸循环异常可较早突出","气道与急救优先","不要等待瞳孔改变才处理"],"source":"D10:P0008–P0028、P0079–P0118","id":"neuro-diagnosis-6"}],"labs":[{"topic":"头颅CT","cells":["急性出血常高密度；梗死早期可无明显改变","分型及紧急排查","CT早期未见梗死不等于排除缺血"],"source":"D10:P0029–P0078、P0127–P0140","id":"neuro-labs-0"},{"topic":"MRI/DWI","cells":["早期缺血灶及部分后颅窝病变评估","按场景补充信息","检查适用与时机由流程决定"],"source":"D10:P0029–P0078、P0127–P0140","id":"neuro-labs-1"},{"topic":"硬膜外/下CT形态","cells":["讲义：前者双凸透镜样，后者常新月样","影像鉴别线索","需要专业影像解释"],"source":"D10:P0029–P0078、P0127–P0140","id":"neuro-labs-2"},{"topic":"CTA/MRA/DSA等","cells":["血管病变、狭窄、动脉瘤等评估","病因和治疗规划","非每例都需要同一侵入检查"],"source":"D10:P0029–P0078、P0127–P0140","id":"neuro-labs-3"},{"topic":"意识、瞳孔与神经查体","cells":["GCS各项及动态变化，瞳孔大小反应、肢体语言","趋势反映恶化或恢复","镇静等因素影响评分"],"source":"D10:P0029–P0078、P0127–P0140","id":"neuro-labs-4"},{"topic":"血糖、凝血等","cells":["代谢模拟病、治疗资格与风险评估","结合最后正常时间与影像","不能凭单一数值自行决定溶栓"],"source":"D10:P0029–P0078、P0127–P0140","id":"neuro-labs-5"},{"topic":"腰穿风险","cells":["颅内压高、占位/脑疝等须严格评估禁忌","具体疑SAH路径由专业流程判断","不把讲义腰穿段落当自主检查指令"],"source":"D10:P0029–P0078、P0127–P0140","id":"neuro-labs-6"}],"treatment":[{"topic":"缺血性卒中","cells":["再灌注、抗栓等依时间、分型与禁忌评估","恢复灌注并防复发","不是所有卒中都能溶栓/抗凝"],"source":"D10:P0143–P0164、P0216–P0225、P0226–P0257","id":"neuro-treatment-0"},{"topic":"脑出血/颅内高压","cells":["按血压、颅压、出血及病因处理","监测神经与器官状态","甘露醇、激素等不按讲义固定组合普用"],"source":"D10:P0143–P0164、P0216–P0225、P0226–P0257","id":"neuro-treatment-1"},{"topic":"脑疝/气道威胁","cells":["紧急报告并配合气道和专科处理","维护生命功能、准备进一步治疗","不等常规查房或完整检查"],"source":"D10:P0143–P0164、P0216–P0225、P0226–P0257","id":"neuro-treatment-2"},{"topic":"癫痫与脑外伤","cells":["发作时保护安全与气道，病因和药物依医嘱","记录发作类型、时长及恢复","不向口中塞物或强行压住肢体"],"source":"D10:P0143–P0164、P0216–P0225、P0226–P0257","id":"neuro-treatment-3"},{"topic":"康复与二级预防","cells":["稳定后语言、吞咽、运动训练和危险因素管理","以功能和安全为目标","不能把早期康复理解成无条件强行活动"],"source":"D10:P0143–P0164、P0216–P0225、P0226–P0257","id":"neuro-treatment-4"}],"nursing":[{"topic":"卒中时间信息","cells":["最后正常时间与症状发现时间分别记录","支持急救路径","不能用到院时间代替发病时间"],"source":"D10:P0121–P0159、P0220–P0225、P0256–P0278","id":"neuro-nursing-0"},{"topic":"气道与吞咽","cells":["意识/吞咽不明时不随意喂水药","筛查后安排性状、体位和途径","清醒也可能吞咽障碍"],"source":"D10:P0121–P0159、P0220–P0225、P0256–P0278","id":"neuro-nursing-1"},{"topic":"颅压危险观察","cells":["意识、瞳孔、呼吸、血压和新缺损比较","恶化立即报告","单一分数正常不能覆盖趋势恶化"],"source":"D10:P0121–P0159、P0220–P0225、P0256–P0278","id":"neuro-nursing-2"},{"topic":"功能与皮肤","cells":["良肢位、按耐受活动、减压及营养","预防失用、压力伤和并发症","不按摩已受损受压部位"],"source":"D10:P0121–P0159、P0220–P0225、P0256–P0278","id":"neuro-nursing-3"},{"topic":"脑脊液漏","cells":["观察鼻/耳漏液，防污染和不当操作","避免自行填塞、冲洗及经鼻操作","体位和其他处理按具体损伤评估"],"source":"D10:P0121–P0159、P0220–P0225、P0256–P0278","id":"neuro-nursing-4"},{"topic":"出院指导","cells":["按医嘱用药、自测危险因素、家属训练","突然无力、言语异常、剧烈头痛及时就医","症状短暂恢复也需评估"],"source":"D10:P0121–P0159、P0220–P0225、P0256–P0278","id":"neuro-nursing-5"}]},"hematology":{"diagnosis":[{"topic":"缺铁性贫血","cells":["小细胞低色素背景，铁储备/代谢指标支持","查缺铁病因","不能只按Hb低判断缺铁"],"source":"D12:P0012–P0015、D13:P0039–P0059","id":"hematology-diagnosis-0"},{"topic":"巨幼细胞性贫血","cells":["大细胞背景、叶酸/B12相关缺乏","结合血象与病因","治疗前需区分缺乏类型"],"source":"D12:P0012–P0015、D13:P0039–P0059","id":"hematology-diagnosis-1"},{"topic":"溶血性贫血","cells":["贫血、黄疸、脾大，可伴网织红细胞/间胆升高","查溶血证据及病因","Coombs阳性支持部分免疫性病因，不代表全部"],"source":"D12:P0012–P0015、D13:P0039–P0059","id":"hematology-diagnosis-2"},{"topic":"再生障碍性贫血","cells":["全血细胞减少＋骨髓造血低下","排除其他骨髓/血液病","不能只用外周血一项定病名"],"source":"D12:P0012–P0015、D13:P0039–P0059","id":"hematology-diagnosis-3"},{"topic":"ITP与IgA血管炎","cells":["前者以血小板减少出血为线索；后者紫癜可伴腹/关节/肾表现、血小板常正常","区分血小板问题和血管炎","需排其他病因"],"source":"D12:P0012–P0015、D13:P0039–P0059","id":"hematology-diagnosis-4"},{"topic":"DIC","cells":["基础病＋出血/灌注异常，血小板、凝血及纤溶变化","动态综合判断","单次D二聚体高不能确诊"],"source":"D12:P0012–P0015、D13:P0039–P0059","id":"hematology-diagnosis-5"},{"topic":"白血病/淋巴瘤/骨髓瘤","cells":["发热贫血出血浸润；淋巴结/B症状；骨痛肾损害等各有组合","需要病理、免疫/遗传等分型","原讲义白细胞必高、原始细胞固定阈值不能覆盖全部现代分类"],"source":"D12:P0012–P0015、D13:P0039–P0059","id":"hematology-diagnosis-6"}],"labs":[{"topic":"血常规分类","cells":["Hb、红细胞指标、白细胞分类/绝对值、血小板","区分贫血、感染及出血风险","总白细胞不能代替中性粒绝对值"],"source":"D13:P0060–P0065、P0073–P0081","id":"hematology-labs-0"},{"topic":"网织红细胞","cells":["反映红细胞生成反应","与失血/溶血及骨髓状态结合","需用绝对值/校正等适用解释"],"source":"D13:P0060–P0065、P0073–P0081","id":"hematology-labs-1"},{"topic":"铁蛋白与铁代谢","cells":["铁储备及可用铁线索","支持缺铁等鉴别","炎症可影响铁蛋白，不能单项排除"],"source":"D13:P0060–P0065、P0073–P0081","id":"hematology-labs-2"},{"topic":"PT/APTT、纤维蛋白原等","cells":["凝血途径和消耗相关信息","DIC、血友病等鉴别","抗凝药和检验条件影响结果"],"source":"D13:P0060–P0065、P0073–P0081","id":"hematology-labs-3"},{"topic":"骨髓检查","cells":["增生、细胞类型及病理","血液病诊断分型","不是只看“增生活跃”四字"],"source":"D13:P0060–P0065、P0073–P0081","id":"hematology-labs-4"},{"topic":"免疫/遗传/分子","cells":["亚型、靶标与预后相关信息","指导精准分型及治疗","不能只靠FAB口诀取代现代分类"],"source":"D13:P0060–P0065、P0073–P0081","id":"hematology-labs-5"}],"treatment":[{"topic":"口服铁剂","cells":["补铁并处理缺铁原因","观察胃肠反应、Hb与铁储备恢复","服法和疗程按具体制剂/方案"],"source":"D13:P0088–P0133","id":"hematology-treatment-0"},{"topic":"铁剂宣教","cells":["部分食物饮品/药物影响吸收；可有黑便","解释相互作用和不适","只有液体剂型才涉及吸管，黑便仍需结合出血症状"],"source":"D13:P0088–P0133","id":"hematology-treatment-1"},{"topic":"免疫抑制等","cells":["再障或部分免疫性血液病按方案","感染、血象、肝肾和药物反应监测","不以一个病名自行配药"],"source":"D13:P0088–P0133","id":"hematology-treatment-2"},{"topic":"化疗治疗","cells":["按亚型、方案和通路规范实施","观察骨髓抑制、胃肠及器官毒性","给药顺序与外渗处理按具体药物"],"source":"D13:P0088–P0133","id":"hematology-treatment-3"},{"topic":"化疗外渗","cells":["立即停止相关输注并报告，后续按药物流程","标记范围、观察组织、记录处理","不一律冷敷/热敷，也不盲目冲管"],"source":"D13:P0088–P0133","id":"hematology-treatment-4"},{"topic":"血液成分支持","cells":["按贫血、出血及评估配合输血","核对、观察反应及疗效","不是所有低血小板或Hb一律同阈值输注"],"source":"D13:P0088–P0133","id":"hematology-treatment-5"}],"nursing":[{"topic":"贫血活动","cells":["依据症状与程度安排休息、协助活动","观察心悸、气促、头晕及耐受","活动与氧疗不只按Hb数字套"],"source":"D13:P0134–P0199","id":"hematology-nursing-0"},{"topic":"出血防护","cells":["皮肤、口腔、鼻腔、排便和穿刺分别防损伤","记录部位量及变化","现存出血与其他部位风险分开写"],"source":"D13:P0134–P0199","id":"hematology-nursing-1"},{"topic":"颅内出血警讯","cells":["头痛、呕吐、视物或意识变化","立即报告并准备急救","不能只继续观察瘀点"],"source":"D13:P0134–P0199","id":"hematology-nursing-2"},{"topic":"感染预防","cells":["手卫生、口腔皮肤、肛周与导管维护","发热寻找感染灶并按流程留标本","粒细胞减少者具体保护措施个体化"],"source":"D13:P0134–P0199","id":"hematology-nursing-3"},{"topic":"化疗毒性线索","cells":["蒽环类心脏、长春新碱周围神经、CTX膀胱等","按药物观察特定表现与检查","此为学习关联，不代表全部药物风险"],"source":"D13:P0134–P0199","id":"hematology-nursing-4"},{"topic":"心理与形象","cells":["脱发、反复治疗、恐惧及家庭支持","解释流程，支持生活能力","不以“保持乐观”代替具体帮助"],"source":"D13:P0134–P0199","id":"hematology-nursing-5"}]},"rheumatology":{"diagnosis":[{"topic":"SLE","cells":["光敏皮疹、口腔溃疡、关节症状及肾/血液等多系统表现","联合免疫学与临床评估","ANA阳性不独立确诊"],"source":"D14:P0003–P0028","id":"rheumatology-diagnosis-0"},{"topic":"RA","cells":["对称小关节肿痛、晨僵和功能受限，可能侵蚀变形","关注慢性炎性关节表现","晨僵时长仅为线索，不能一项定诊"],"source":"D14:P0003–P0028","id":"rheumatology-diagnosis-1"},{"topic":"系统与局部的区别","cells":["SLE以多器官组合；RA以关节滑膜病变为主但也可系统受累","避免看见关节痛就混用病名","两者均需评估感染和其他病因"],"source":"D14:P0003–P0028","id":"rheumatology-diagnosis-2"}],"labs":[{"topic":"ANA","cells":["常用筛查线索，特异性有限","与临床及其他抗体联合","不能用阳性解释全部症状"],"source":"D14:P0029–P0090","id":"rheumatology-labs-0"},{"topic":"抗dsDNA与补体","cells":["抗体变化、C3/C4降低可提示SLE活动方向","联系肾脏及系统表现","不以单次滴度决定治疗"],"source":"D14:P0029–P0090","id":"rheumatology-labs-1"},{"topic":"抗Sm","cells":["特异性较高的SLE支持证据","诊断线索","敏感性有限，非可靠活动性单项指标"],"source":"D14:P0029–P0090","id":"rheumatology-labs-2"},{"topic":"RF与ACPA/抗CCP","cells":["RA相关免疫线索，ACPA有早期/预后价值","联合关节表现与影像","RF阴性不排RA、阳性不独立确诊"],"source":"D14:P0029–P0090","id":"rheumatology-labs-3"},{"topic":"ESR/CRP、血象","cells":["炎症及贫血/血细胞改变","活动与其他原因评估","不能独立区分活动和感染"],"source":"D14:P0029–P0090","id":"rheumatology-labs-4"},{"topic":"尿检、肾功能/肾活检","cells":["蛋白尿、血尿、管型及滤过变化；必要时病理","狼疮肾炎评估","并非所有患者必须活检"],"source":"D14:P0029–P0090","id":"rheumatology-labs-5"},{"topic":"X线/MRI、滑液","cells":["侵蚀、间隙、滑膜等；滑液帮助鉴别感染/晶体","结构分期和鉴别","原讲义“X线>抗体”的统一排名不作为诊断规则"],"source":"D14:P0029–P0090","id":"rheumatology-labs-6"}],"treatment":[{"topic":"NSAIDs","cells":["缓解炎性疼痛等症状","观察胃肠、肾脏和其他风险","症状改善不等于已控制全部疾病"],"source":"D14:P0105–P0114","id":"rheumatology-treatment-0"},{"topic":"糖皮质激素","cells":["按器官和活动状态使用","监测感染、血压血糖、骨骼和胃肠","不自行骤停或套“人人首选”"],"source":"D14:P0105–P0114","id":"rheumatology-treatment-1"},{"topic":"DMARDs/免疫抑制","cells":["控制疾病过程，具体药物按病情","血象、肝肾、感染及特异风险","育龄用药须核对生殖相关要求"],"source":"D14:P0105–P0114","id":"rheumatology-treatment-2"},{"topic":"羟氯喹","cells":["部分SLE长期方案的重要药物","按方案眼部等监测","不能因无症状忽略复查"],"source":"D14:P0105–P0114","id":"rheumatology-treatment-3"},{"topic":"生物制剂","cells":["按方案筛查结核、肝炎等感染相关风险","观察感染与过敏","筛查、适应证和停药由团队评估"],"source":"D14:P0105–P0114","id":"rheumatology-treatment-4"}],"nursing":[{"topic":"SLE皮肤","cells":["防晒，温和清洁，减少刺激和抓伤","观察新皮疹及破损","不以统一“禁所有护肤品”代替皮肤评估"],"source":"D14:P0115–P0136","id":"rheumatology-nursing-0"},{"topic":"口腔溃疡","cells":["清洁、疼痛与进食护理","记录溃疡、感染及营养影响","具体漱口制剂按评估"],"source":"D14:P0115–P0136","id":"rheumatology-nursing-1"},{"topic":"RA晨僵","cells":["适当温热舒适护理和渐进活动","观察僵硬时长及功能","感觉/血供异常者温热需谨慎"],"source":"D14:P0115–P0136","id":"rheumatology-nursing-2"},{"topic":"关节功能","cells":["功能位、辅助器具、被动到主动循序推进","以疼痛及耐受调整","不长期固定不动，也不强行按摩急性关节"],"source":"D14:P0115–P0136","id":"rheumatology-nursing-3"},{"topic":"系统受累","cells":["尿量、体重、肾功能与意识/精神变化","及时报告器官受累线索","饮食和水分按肾心状态调整"],"source":"D14:P0115–P0136","id":"rheumatology-nursing-4"}]},"shock-burn":{"diagnosis":[{"topic":"等渗性失水","cells":["消化液急丢失、第三间隙、烧伤等；钠可在正常范围","同时失水失钠，仍可有低灌注","血钠正常不排除严重体液不足"],"source":"D17:P0008–P0022、P0039–P0059、P0175–P0200","id":"shock-burn-diagnosis-0"},{"topic":"低渗性失水","cells":["失钠多于失水，可见低钠、乏力头晕及循环异常","联系持续丢失和补液史","低钠的容量状态不只有脱水"],"source":"D17:P0008–P0022、P0039–P0059、P0175–P0200","id":"shock-burn-diagnosis-1"},{"topic":"高渗性失水","cells":["失水相对多，口渴、脱水及神经表现","联系摄入不足、发热等","讲义钠＞150口径不可替代完整高钠评估"],"source":"D17:P0008–P0022、P0039–P0059、P0175–P0200","id":"shock-burn-diagnosis-2"},{"topic":"低钾/高钾","cells":["讲义分别＜3.5与＞5.5 mmol/L","两者均可有肌无力及心律问题","范围按实验室/适用标准核对"],"source":"D17:P0008–P0022、P0039–P0059、P0175–P0200","id":"shock-burn-diagnosis-3"},{"topic":"烧伤面积","cells":["成人九分法作估计，儿童分布需调整","Ⅱ/Ⅲ度等计入相应复苏面积口径","不把浅表红斑直接算进所有公式"],"source":"D17:P0008–P0022、P0039–P0059、P0175–P0200","id":"shock-burn-diagnosis-4"},{"topic":"吸入损伤","cells":["烟雾环境、口鼻烟灰、声嘶和气道症状","早期气道危险评估","血氧读数正常不能覆盖所有烟雾/CO风险"],"source":"D17:P0008–P0022、P0039–P0059、P0175–P0200","id":"shock-burn-diagnosis-5"}],"labs":[{"topic":"低钾心电","cells":["T波低平/倒置、U波等","结合血钾与临床","心电不典型不排除"],"source":"D17:P0057–P0059、P0081–P0103、P0123–P0128","id":"shock-burn-labs-0"},{"topic":"高钾心电","cells":["高尖T波、QRS增宽等可能出现","评估传导/心律风险","正常心电不能保证高钾安全"],"source":"D17:P0057–P0059、P0081–P0103、P0123–P0128","id":"shock-burn-labs-1"},{"topic":"酸碱基础","cells":["讲义pH 7.35–7.45，PaCO₂ 35–45mmHg","酸血症/碱血症与呼吸因素初步判断","代偿和混合紊乱需进一步计算"],"source":"D17:P0057–P0059、P0081–P0103、P0123–P0128","id":"shock-burn-labs-2"},{"topic":"HCO₃⁻、BE、AG","cells":["讲义列HCO₃⁻22–27、BE±3、AG8–12 mmol/L","代谢及酸负荷线索","参考区间依实验室、AG需考虑白蛋白"],"source":"D17:P0057–P0059、P0081–P0103、P0123–P0128","id":"shock-burn-labs-3"},{"topic":"乳酸","cells":["讲义以＜2 mmol/L为参考","低灌注等评估及趋势","升高不只由组织低氧造成"],"source":"D17:P0057–P0059、P0081–P0103、P0123–P0128","id":"shock-burn-labs-4"},{"topic":"复苏观察","cells":["尿量、意识、皮温、血压、氧合与酸碱联合","判断效果和器官变化","不以CVP或“尿量＞30”一项宣布复苏完成"],"source":"D17:P0057–P0059、P0081–P0103、P0123–P0128","id":"shock-burn-labs-5"}],"treatment":[{"topic":"失水纠正","cells":["液体选择、量和速度依类型、循环与持续损失","复评电解质及灌注","不能套所有患者先快后慢"],"source":"D17:P0060–P0080、P0118–P0145、P0202–P0214","id":"shock-burn-treatment-0"},{"topic":"补钾","cells":["按血钾、排泄、途径及医嘱安排","观察心律、静脉与血钾变化","不得静脉推注氯化钾；滴速需用泵和明确单位"],"source":"D17:P0060–P0080、P0118–P0145、P0202–P0214","id":"shock-burn-treatment-1"},{"topic":"高钾处理","cells":["保护心肌、转移钾、清除钾、处理来源","同时监测血糖与心律","不是所有患者一套固定剂量"],"source":"D17:P0060–P0080、P0118–P0145、P0202–P0214","id":"shock-burn-treatment-2"},{"topic":"休克病因","cells":["失血要控制出血，感染要控制感染源等","循环支持与病因并行","心源性等不能机械大量补液"],"source":"D17:P0060–P0080、P0118–P0145、P0202–P0214","id":"shock-burn-treatment-3"},{"topic":"烧伤复苏估算","cells":["讲义成人首24h：体重×面积百分数×1.5ml＋基础水量口径","理解面积写30而非0.30，时间从受伤算","仅为本讲义公式记忆，不是通用处方；年龄、伤情及复评改变方案"],"source":"D17:P0060–P0080、P0118–P0145、P0202–P0214","id":"shock-burn-treatment-4"}],"nursing":[{"topic":"气道与呼吸","cells":["烟灰声嘶、呼吸功、意识、氧合及血气","立即报告气道恶化并配合处理","不能只观察皮肤创面"],"source":"D17:P0123–P0142、P0203–P0208","id":"shock-burn-nursing-0"},{"topic":"灌注记录","cells":["意识、肢端皮温、心率血压、尿量与液体输入","动态比较并报告恶化","休克早期血压可尚正常"],"source":"D17:P0123–P0142、P0203–P0208","id":"shock-burn-nursing-1"},{"topic":"创面保护","cells":["脱离热源、清洁覆盖并防污染","避免不当涂抹和额外损伤","大面积烧伤需防低体温"],"source":"D17:P0123–P0142、P0203–P0208","id":"shock-burn-nursing-2"},{"topic":"输液安全","cells":["核对泵速、通路和药物，观察外渗及呼吸变化","避免不足与过负荷","心肾异常需个体化"],"source":"D17:P0123–P0142、P0203–P0208","id":"shock-burn-nursing-3"},{"topic":"基础护理","cells":["皮肤、口腔、管路、安全和营养共同安排","预防感染及压力损伤","不把每2小时翻身当不顾稳定性的绝对动作"],"source":"D17:P0123–P0142、P0203–P0208","id":"shock-burn-nursing-4"}]},"thorax-breast":{"diagnosis":[{"topic":"乳腺癌线索","cells":["无痛质硬肿块、皮肤凹陷、橘皮/乳头改变及可疑结节","影像和取样评估","不把任何一项体征当确诊"],"source":"D16:P0038–P0050、P0130–P0138","id":"thorax-breast-diagnosis-0"},{"topic":"开放性气胸","cells":["胸壁开放伤伴呼吸困难，可能有吸吮声","气道及胸伤急救评估","开放伤处理按现场专业流程"],"source":"D16:P0038–P0050、P0130–P0138","id":"thorax-breast-diagnosis-1"},{"topic":"张力性气胸","cells":["通气受损并可迅速循环恶化、低血压","需紧急专业处理","不等影像/所有典型体征才报告"],"source":"D16:P0038–P0050、P0130–P0138","id":"thorax-breast-diagnosis-2"},{"topic":"连枷胸方向","cells":["多根多处骨折可见反常胸壁运动","结合肺挫伤和通气","不能仅靠外部固定替代整体呼吸评估"],"source":"D16:P0038–P0050、P0130–P0138","id":"thorax-breast-diagnosis-3"}],"labs":[{"topic":"乳腺超声/钼靶","cells":["结节囊实性、形态钙化及周围改变","风险评估和进一步取样","依年龄与情况选适合检查"],"source":"D16:P0045–P0050、P0147–P0167","id":"thorax-breast-labs-0"},{"topic":"病理取样","cells":["组织/细胞学性质","明确病变、指导治疗","具体活检方式由评估选择"],"source":"D16:P0045–P0050、P0147–P0167","id":"thorax-breast-labs-1"},{"topic":"胸部影像","cells":["积气、积液、骨折及肺病变","诊断和复张评估","危急张力性气胸不等待检查才处理"],"source":"D16:P0045–P0050、P0147–P0167","id":"thorax-breast-labs-2"},{"topic":"呼吸与循环指标","cells":["血氧、血气、血压、意识趋势","通气/氧合及灌注","症状和监测必须结合"],"source":"D16:P0045–P0050、P0147–P0167","id":"thorax-breast-labs-3"},{"topic":"胸管记录","cells":["液体色质量、气泡、水柱及系统状态","联系漏气、阻塞或肺复张等","不能只看无波动就断定堵管"],"source":"D16:P0045–P0050、P0147–P0167","id":"thorax-breast-labs-4"}],"treatment":[{"topic":"气胸急救与引流","cells":["按气胸类型、程度及生理影响配合处理","缓解胸腔压力与通气受限","穿刺等由有资质人员按流程实施"],"source":"D16:P0051–P0084、P0138–P0152","id":"thorax-breast-treatment-0"},{"topic":"镇痛与呼吸支持","cells":["使患者能更好通气、排痰及恢复活动","观察镇痛效果与呼吸抑制等","不以痛缓解代表胸伤已安全"],"source":"D16:P0051–P0084、P0138–P0152","id":"thorax-breast-treatment-1"},{"topic":"乳腺手术/综合治疗","cells":["按分期、亚型及方案选择","病因治疗与恢复并行","讲义妊娠/哺乳处理绝对表述不作为通用规则"],"source":"D16:P0051–P0084、P0138–P0152","id":"thorax-breast-treatment-2"},{"topic":"术后康复","cells":["按重建、皮瓣、伤口和活动计划递进","维护功能及生活能力","不能所有人按同一天数举肩"],"source":"D16:P0051–P0084、P0138–P0152","id":"thorax-breast-treatment-3"}],"nursing":[{"topic":"乳腺皮瓣","cells":["颜色温度、贴合、伤口渗血/积液","异常及时报告，防压迫和牵拉","具体包扎由术式和医嘱决定"],"source":"D16:P0056–P0084、P0153–P0171","id":"thorax-breast-nursing-0"},{"topic":"上肢远端","cells":["皮温、肤色、麻木、肿胀与血运","区分包扎压迫及淋巴回流问题","不自行用力按摩肿胀肢体"],"source":"D16:P0056–P0084、P0153–P0171","id":"thorax-breast-nursing-1"},{"topic":"胸管位置与密闭","cells":["系统直立、低于引流口，连接固定","防牵拉、折叠和逆流","距离、水封深度依装置标准"],"source":"D16:P0056–P0084、P0153–P0171","id":"thorax-breast-nursing-2"},{"topic":"胸管异常","cells":["气促、胸闷、引流突变或装置异常","即时评估并按流程报告/处理","不普遍常规夹管、挤管"],"source":"D16:P0056–P0084、P0153–P0171","id":"thorax-breast-nursing-3"},{"topic":"拔管后","cells":["看呼吸、血氧、伤口漏气/渗液和皮下气肿","发现复发或并发症","拔管不只靠留置天数或一个量值"],"source":"D16:P0056–P0084、P0153–P0171","id":"thorax-breast-nursing-4"},{"topic":"功能与出院","cells":["呼吸训练、上肢活动、伤口与异常信号","患者/家属能演示并说明","活动限制需随术式调整"],"source":"D16:P0056–P0084、P0153–P0171","id":"thorax-breast-nursing-5"}]},"urology-surgery":{"diagnosis":[{"topic":"肾损伤","cells":["外伤、腰腹痛、血尿及可能低灌注","结合影像与全身状态","血尿程度不等于损伤严重度"],"source":"D18:P0008–P0057","id":"urology-surgery-diagnosis-0"},{"topic":"膀胱/尿道损伤","cells":["外伤后血尿、尿道口出血、排尿困难等","查部位、尿外渗和合并伤","疑尿道损伤不能反复盲目导尿"],"source":"D18:P0008–P0057","id":"urology-surgery-diagnosis-1"},{"topic":"尿路结石","cells":["绞痛向下放射、血尿及可能梗阻","关注发热少尿/无尿","感染＋梗阻比普通疼痛更急"],"source":"D18:P0008–P0057","id":"urology-surgery-diagnosis-2"},{"topic":"BPH","cells":["尿频、进行性排尿困难、残余尿/潴留","结合症状和检查","不能按年龄直接归因良性增生"],"source":"D18:P0008–P0057","id":"urology-surgery-diagnosis-3"},{"topic":"膀胱癌线索","cells":["无痛性、间歇性肉眼血尿","内镜等进一步评估","血尿自行停止不等于病因消失"],"source":"D18:P0008–P0057","id":"urology-surgery-diagnosis-4"},{"topic":"肾癌/前列腺癌","cells":["血尿、肿块/疼痛或异常PSA/指检等线索","影像、病理及分期","传统三联征和单次PSA均不能覆盖全部"],"source":"D18:P0008–P0057","id":"urology-surgery-diagnosis-5"}],"labs":[{"topic":"尿常规/培养","cells":["红细胞、白细胞、培养药敏","出血与感染方向","尿pH不能独立决定结石成分"],"source":"D18:P0058–P0129","id":"urology-surgery-labs-0"},{"topic":"血常规/肾功能/电解质","cells":["失血、感染、排泄与代谢变化","评估损伤、梗阻和术后并发症","Hb变化结合时间与补液"],"source":"D18:P0058–P0129","id":"urology-surgery-labs-1"},{"topic":"结石成分与代谢","cells":["分析排出结石，结合尿/血代谢","用于复发预防","不是所有结石统一低钙饮食"],"source":"D18:P0058–P0129","id":"urology-surgery-labs-2"},{"topic":"超声/CT及尿路成像","cells":["结石、积水、肾损伤和肿瘤等","定位并评估范围","检查选择依辐射、造影和肾功能"],"source":"D18:P0058–P0129","id":"urology-surgery-labs-3"},{"topic":"膀胱镜＋必要活检","cells":["直视病变及取样","血尿和肿瘤诊断","侵入性检查有准备及风险评估"],"source":"D18:P0058–P0129","id":"urology-surgery-labs-4"},{"topic":"PSA/直肠指检","cells":["前列腺相关风险线索","决定进一步评估","原讲义“PSA正常可排除癌”不成立，不作为排除规则"],"source":"D18:P0058–P0129","id":"urology-surgery-labs-5"}],"treatment":[{"topic":"结石非手术/手术","cells":["按大小位置、梗阻、感染、肾功能等选择","解除问题并保护肾功能","发热无尿不只建议多饮水或跳跃"],"source":"D18:P0239–P0248、P0251–P0287","id":"urology-surgery-treatment-0"},{"topic":"解除梗阻","cells":["引流或手术等依病情","感染控制与通畅并行","方式由专业评估"],"source":"D18:P0239–P0248、P0251–P0287","id":"urology-surgery-treatment-1"},{"topic":"前列腺/膀胱手术","cells":["结合具体术式安排引流及后续治疗","恢复排尿、处理病变","TURP、膀胱手术护理不混成一套"],"source":"D18:P0239–P0248、P0251–P0287","id":"urology-surgery-treatment-2"},{"topic":"膀胱灌注","cells":["局部治疗按方案实施","观察刺激症状、血尿及其他反应","保留时长、药物和复诊服从方案"],"source":"D18:P0239–P0248、P0251–P0287","id":"urology-surgery-treatment-3"},{"topic":"术后并发症","cells":["出血、感染、尿漏、液体/电解质问题等分别处理","按症状与检查定位","不能所有血尿都仅加快冲洗"],"source":"D18:P0239–P0248、P0251–P0287","id":"urology-surgery-treatment-4"}],"nursing":[{"topic":"膀胱冲洗计量","cells":["实际尿量＝总引流量－冲洗液量","分别记录输入和流出","总袋量不能当自身尿量"],"source":"D18:P0253–P0284、P0302–P0309","id":"urology-surgery-nursing-0"},{"topic":"冲洗观察","cells":["颜色血块、通畅、腹胀疼痛和生命体征","及时识别堵塞/出血并报告","不得暴力推注"],"source":"D18:P0253–P0284、P0302–P0309","id":"urology-surgery-nursing-1"},{"topic":"双J管","cells":["观察排尿症状、血尿、疼痛发热及活动耐受","明确复查和移除计划","饮水按心肾和医嘱，不一律大量"],"source":"D18:P0253–P0284、P0302–P0309","id":"urology-surgery-nursing-2"},{"topic":"肾造瘘/引流","cells":["固定、低位、通畅与色质量","防逆流、牵拉和感染","不能自行夹管/拔管"],"source":"D18:P0253–P0284、P0302–P0309","id":"urology-surgery-nursing-3"},{"topic":"TURP相关综合征方向","cells":["术后呼吸困难、意识变化、容量/低钠问题","及时查相关指标并报告","风险与技术、冲洗液及吸收有关，不一律套某药"],"source":"D18:P0253–P0284、P0302–P0309","id":"urology-surgery-nursing-4"},{"topic":"居家复诊","cells":["留管种类、护理与异常就医，结石复发预防","学生能区分各管路目的","不要把管子留到“没感觉”才处理"],"source":"D18:P0253–P0284、P0302–P0309","id":"urology-surgery-nursing-5"}]},"hepatobiliary":{"diagnosis":[{"topic":"胆囊炎/结石","cells":["右上腹痛可向肩背放射，发热、Murphy征等","结合超声与临床","疼痛餐后发生不独立确诊"],"source":"D20:P0069–P0087、P0200–P0203","id":"hepatobiliary-diagnosis-0"},{"topic":"胆管炎","cells":["腹痛、寒战高热、黄疸的Charcot组合","梗阻感染方向","不必完整三联征才评估"],"source":"D20:P0069–P0087、P0200–P0203","id":"hepatobiliary-diagnosis-1"},{"topic":"重症胆管炎","cells":["前述背景加低血压、意识变化等","感染及器官功能风险","不能等五联征齐全再升级"],"source":"D20:P0069–P0087、P0200–P0203","id":"hepatobiliary-diagnosis-2"},{"topic":"胰腺疾病","cells":["持续上腹向背痛、酶学/影像等","结合内外科共同路径","重症不能只凭旧“出血坏死型”称谓"],"source":"D20:P0069–P0087、P0200–P0203","id":"hepatobiliary-diagnosis-3"},{"topic":"术后胆/胰瘘","cells":["异常引流＋腹痛发热或脏器变化","需要液体检查/影像及临床","不凭颜色单独确诊"],"source":"D20:P0069–P0087、P0200–P0203","id":"hepatobiliary-diagnosis-4"}],"labs":[{"topic":"胆红素、肝酶、血象/凝血","cells":["胆道梗阻、感染与肝功能影响","同时评估器官及手术风险","异常来源需结合病史"],"source":"D20:P0005–P0011、P0088–P0124","id":"hepatobiliary-labs-0"},{"topic":"超声","cells":["胆囊、胆管、结石和扩张线索","初步定位及引导","准备按项目要求，不统一给所有人禁食时间"],"source":"D20:P0005–P0011、P0088–P0124","id":"hepatobiliary-labs-1"},{"topic":"MRCP","cells":["非侵入性胆胰管成像","结构与梗阻评估","金属/设备安全需核查"],"source":"D20:P0005–P0011、P0088–P0124","id":"hepatobiliary-labs-2"},{"topic":"ERCP","cells":["可成像、取样并实施部分治疗","取石、引流等途径","观察胰腺炎、出血、穿孔等风险"],"source":"D20:P0005–P0011、P0088–P0124","id":"hepatobiliary-labs-3"},{"topic":"PTC/PTCD","cells":["经皮评估胆道，必要时引流","解除梗阻等","出血及胆汁性腹膜炎等需观察"],"source":"D20:P0005–P0011、P0088–P0124","id":"hepatobiliary-labs-4"},{"topic":"T管造影","cells":["通畅、狭窄、残余结石等","后续处理/拔管评估","不按固定术后天数替代判断"],"source":"D20:P0005–P0011、P0088–P0124","id":"hepatobiliary-labs-5"},{"topic":"AFP与肝肿瘤影像","cells":["肿瘤标志物结合典型影像等","病因/肿瘤评估","AFP不是单独确诊，非所有肝癌必须穿刺"],"source":"D20:P0005–P0011、P0088–P0124","id":"hepatobiliary-labs-6"}],"treatment":[{"topic":"胆管结石目标","cells":["解除梗阻、控制感染并保持胆汁引流","按情况选择内镜/介入/手术","不是人人同一种术式"],"source":"D20:P0141–P0147、P0167–P0179、P0193–P0203","id":"hepatobiliary-treatment-0"},{"topic":"重症胆道感染","cells":["复苏与抗感染并行，及时感染源控制","维护灌注、器官并解除梗阻","不能只写降温镇痛"],"source":"D20:P0141–P0147、P0167–P0179、P0193–P0203","id":"hepatobiliary-treatment-1"},{"topic":"T管作用","cells":["减压引流、支持后续通畅评估及部分残石处理","联系手术目的","不只背“引流胆汁”四字"],"source":"D20:P0141–P0147、P0167–P0179、P0193–P0203","id":"hepatobiliary-treatment-2"},{"topic":"胰腺术后","cells":["针对感染、出血、瘘与营养问题处理","引流、体液与营养协同","液体和药物按方案"],"source":"D20:P0141–P0147、P0167–P0179、P0193–P0203","id":"hepatobiliary-treatment-3"},{"topic":"肝癌局部/综合治疗","cells":["手术、介入等依分期及肝功能安排","观察术后/介入反应","不把AFP一个阈值直接变成治疗决定"],"source":"D20:P0141–P0147、P0167–P0179、P0193–P0203","id":"hepatobiliary-treatment-4"}],"nursing":[{"topic":"T管固定/位置","cells":["防折叠、受压、牵拉及逆流","观察管口、连接和皮肤","不自行冲洗或夹管"],"source":"D20:P0094–P0124、P0155–P0163、P0172–P0203","id":"hepatobiliary-nursing-0"},{"topic":"胆汁观察","cells":["色、清浊、量与腹痛发热黄疸联系","记录突然无引流或异常变化","正常量随阶段和情况变化，不统一一值"],"source":"D20:P0094–P0124、P0155–P0163、P0172–P0203","id":"hepatobiliary-nursing-1"},{"topic":"拔管评估","cells":["恢复、胆道通畅、必要试验和医嘱","移除后观察渗漏与腹部变化","不只靠10–14天口径"],"source":"D20:P0094–P0124、P0155–P0163、P0172–P0203","id":"hepatobiliary-nursing-2"},{"topic":"ERCP后观察","cells":["腹痛、发热、血象/胰酶及生命体征等","识别胰腺炎、出血或穿孔","饮食恢复按实际操作与方案"],"source":"D20:P0094–P0124、P0155–P0163、P0172–P0203","id":"hepatobiliary-nursing-3"},{"topic":"胰瘘/消化液皮损","cells":["液体性状、量、腹部及管周皮肤","引流有效与营养支持并行","不自行按分泌物颜色认定瘘类型"],"source":"D20:P0094–P0124、P0155–P0163、P0172–P0203","id":"hepatobiliary-nursing-4"},{"topic":"重症监测","cells":["意识、血压、尿量、氧合和凝血等","及时报告脏器恶化","不等低血压持续才升级"],"source":"D20:P0094–P0124、P0155–P0163、P0172–P0203","id":"hepatobiliary-nursing-5"}]},"acute-abdomen":{"diagnosis":[{"topic":"单纯机械性肠梗阻","cells":["阵发绞痛、呕吐、腹胀、排气便减少，可有亢进肠鸣音","结合位置/程度及影像","不完全性仍可能有少量排便"],"source":"D21:P0003–P0048、P0167–P0198、P0288–P0297","id":"acute-abdomen-diagnosis-0"},{"topic":"麻痹性肠梗阻","cells":["全腹胀痛、肠鸣音减弱/消失等","结合术后、炎症或代谢背景","不能只按一个肠鸣音判断"],"source":"D21:P0003–P0048、P0167–P0198、P0288–P0297","id":"acute-abdomen-diagnosis-1"},{"topic":"绞窄性危险","cells":["持续剧痛、腹膜刺激、血性排出物及灌注异常","缺血坏死风险","早期体征可不典型"],"source":"D21:P0003–P0048、P0167–P0198、P0288–P0297","id":"acute-abdomen-diagnosis-2"},{"topic":"急性腹膜炎","cells":["压痛、反跳痛、肌紧张及感染中毒表现","寻找穿孔/感染等原因","腹痛轻重不独立决定严重度"],"source":"D21:P0003–P0048、P0167–P0198、P0288–P0297","id":"acute-abdomen-diagnosis-3"},{"topic":"腹部实质/空腔伤","cells":["前者关注出血；后者关注漏出/腹膜炎，两者可并存","联系外伤史与动态变化","初次检查阴性不覆盖病情进展"],"source":"D21:P0003–P0048、P0167–P0198、P0288–P0297","id":"acute-abdomen-diagnosis-4"},{"topic":"阑尾炎","cells":["典型可转移性右下腹痛和局部体征","特殊年龄/位置可不典型","不能因未转移痛就排除"],"source":"D21:P0003–P0048、P0167–P0198、P0288–P0297","id":"acute-abdomen-diagnosis-5"}],"labs":[{"topic":"血常规、炎症信息","cells":["感染/炎症及失血线索","结合腹部与循环状态","单次正常不排急腹症"],"source":"D21:P0094–P0112、P0254–P0265","id":"acute-abdomen-labs-0"},{"topic":"电解质与酸碱","cells":["呕吐、第三间隙和缺血等影响","为补液/纠正提供依据","不能只写“补液”不说明失衡"],"source":"D21:P0094–P0112、P0254–P0265","id":"acute-abdomen-labs-1"},{"topic":"腹部影像","cells":["梗阻部位、游离气、积液及损伤等","按病情选择超声/CT/平片","不把一种影像强制给所有人"],"source":"D21:P0094–P0112、P0254–P0265","id":"acute-abdomen-labs-2"},{"topic":"尿量、灌注与液体损失","cells":["持续丢失及肾灌注信息","复评低血容量和治疗效果","并非单一尿量低就一定缺液"],"source":"D21:P0094–P0112、P0254–P0265","id":"acute-abdomen-labs-3"},{"topic":"腹穿等","cells":["按评估获取液体性质与诊断线索","配合专业诊断","阴性不能机械排除损伤"],"source":"D21:P0094–P0112、P0254–P0265","id":"acute-abdomen-labs-4"}],"treatment":[{"topic":"梗阻支持","cells":["按情况禁食、减压、液体与电解质纠正","缓解胀痛并维护循环","不能用进食或泻药自行“通一通”"],"source":"D21:P0113–P0135、P0250–P0273、P0300–P0314","id":"acute-abdomen-treatment-0"},{"topic":"手术升级","cells":["绞窄/腹膜炎/恶化或非手术无效等","及时准备并处理病因","不等所有红旗齐全"],"source":"D21:P0113–P0135、P0250–P0273、P0300–P0314","id":"acute-abdomen-treatment-1"},{"topic":"镇痛","cells":["评估后依医嘱合理镇痛，持续观察","减少痛苦并监测变化","不传播“未确诊绝对不能镇痛”"],"source":"D21:P0113–P0135、P0250–P0273、P0300–P0314","id":"acute-abdomen-treatment-2"},{"topic":"感染及腹膜污染","cells":["控制感染源及抗感染支持","局部与全身状态一起评估","不能只靠退热"],"source":"D21:P0113–P0135、P0250–P0273、P0300–P0314","id":"acute-abdomen-treatment-3"},{"topic":"阑尾炎路径","cells":["依病情、并发症和方案选手术/非手术","监测转归和手术准备","特殊人群需另评估"],"source":"D21:P0113–P0135、P0250–P0273、P0300–P0314","id":"acute-abdomen-treatment-4"}],"nursing":[{"topic":"腹痛动态","cells":["起止、部位、放射、性质及范围","持续加剧或腹膜刺激变化及时报告","镇痛后仍须复评"],"source":"D21:P0136–P0155、P0253–P0273、P0300–P0314","id":"acute-abdomen-nursing-0"},{"topic":"胃肠减压","cells":["固定通畅、有效性及引流色质量","血性液体、突变与全身症状联系","不自行冲洗/夹闭"],"source":"D21:P0136–P0155、P0253–P0273、P0300–P0314","id":"acute-abdomen-nursing-1"},{"topic":"呕吐安全","cells":["观察意识、体位与呕吐物排出","防误吸，保持口腔清洁","脊柱伤/低灌注等体位另评估"],"source":"D21:P0136–P0155、P0253–P0273、P0300–P0314","id":"acute-abdomen-nursing-2"},{"topic":"出入量营养","cells":["记录损失、尿量、体重与实验室","按阶段安排液体和营养","术后饮食不只按排气或固定天数"],"source":"D21:P0136–P0155、P0253–P0273、P0300–P0314","id":"acute-abdomen-nursing-3"},{"topic":"术后并发症","cells":["再梗阻、感染、瘘和伤口问题分别观察","腹痛发热及粪臭引流等及时报告","不能归为正常恢复一概等待"],"source":"D21:P0136–P0155、P0253–P0273、P0300–P0314","id":"acute-abdomen-nursing-4"},{"topic":"恢复活动","cells":["依稳定和术式渐进活动","预防失用、血栓及恢复生活能力","活动禁忌先核查"],"source":"D21:P0136–P0155、P0253–P0273、P0300–P0314","id":"acute-abdomen-nursing-5"}]},"gi-surgery":{"diagnosis":[{"topic":"食管癌线索","cells":["进行性吞咽困难，早期可哽噎/胸骨后不适","内镜取样评估","单一吞咽困难也有其他原因"],"source":"D22:P0005–P0039、P0117–P0129、P0150–P0158","id":"gi-surgery-diagnosis-0"},{"topic":"胃癌线索","cells":["消瘦、上腹不适、贫血/黑便等，早期可无特异性","胃镜及病理","不把典型晚期表现当早期必需"],"source":"D22:P0005–P0039、P0117–P0129、P0150–P0158","id":"gi-surgery-diagnosis-1"},{"topic":"结肠癌左右差异","cells":["右侧偏贫血/包块，左侧更易梗阻/排便改变","辅助定位线索","不是绝对规则"],"source":"D22:P0005–P0039、P0117–P0129、P0150–P0158","id":"gi-surgery-diagnosis-2"},{"topic":"直肠癌线索","cells":["黏液血便、里急后重、排便不尽或变细","指检、肠镜与取样","不能只当痔疮处理"],"source":"D22:P0005–P0039、P0117–P0129、P0150–P0158","id":"gi-surgery-diagnosis-3"},{"topic":"吻合口瘘/感染","cells":["术后高热、胸/腹痛、气促及异常引流","结合术式与进一步检查","时间窗不是排除条件"],"source":"D22:P0005–P0039、P0117–P0129、P0150–P0158","id":"gi-surgery-diagnosis-4"},{"topic":"倾倒综合征","cells":["讲义早期餐后约30分钟循环/胃肠症状，晚期2–4h低血糖方向","结合手术和进食史","不能把任何餐后不适直接当倾倒"],"source":"D22:P0005–P0039、P0117–P0129、P0150–P0158","id":"gi-surgery-diagnosis-5"}],"labs":[{"topic":"内镜＋病理","cells":["食管/胃/肠病变观察及取样","明确性质","手术/治疗依分期和状态"],"source":"D22:P0005–P0039、P0094–P0129、P0185–P0203","id":"gi-surgery-labs-0"},{"topic":"粪便隐血","cells":["消化道出血筛查线索","帮助决定进一步评估","阴性不排全部肿瘤，阳性不确诊癌"],"source":"D22:P0005–P0039、P0094–P0129、P0185–P0203","id":"gi-surgery-labs-1"},{"topic":"术后血象/生化","cells":["感染、贫血、营养和电解质信息","联合引流和体征","不能只靠白细胞判定瘘"],"source":"D22:P0005–P0039、P0094–P0129、P0185–P0203","id":"gi-surgery-labs-2"},{"topic":"引流液检查/影像","cells":["异常液体、积液及可能瘘的评估","定位并发症","颜色仅是线索"],"source":"D22:P0005–P0039、P0094–P0129、P0185–P0203","id":"gi-surgery-labs-3"},{"topic":"造口评估","cells":["颜色活力、高度形态、排出与周围皮肤","发现缺血、回缩、渗漏等","不只看有没有排便"],"source":"D22:P0005–P0039、P0094–P0129、P0185–P0203","id":"gi-surgery-labs-4"}],"treatment":[{"topic":"肿瘤综合治疗","cells":["按部位、分期及患者状况采用手术及其他治疗","病因与功能恢复兼顾","原讲义“手术唯一治愈”等绝对语不普用"],"source":"D22:P0106–P0129、P0140–P0158、P0182–P0203","id":"gi-surgery-treatment-0"},{"topic":"术后营养","cells":["依据术式、吻合风险和恢复选经口/肠内/肠外","维护营养并降低并发症","不是全部统一禁食几天"],"source":"D22:P0106–P0129、P0140–P0158、P0182–P0203","id":"gi-surgery-treatment-1"},{"topic":"吻合口并发症","cells":["及时评估并配合引流、抗感染、营养等","控制污染和全身影响","是否手术需专业判断"],"source":"D22:P0106–P0129、P0140–P0158、P0182–P0203","id":"gi-surgery-treatment-2"},{"topic":"倾倒相关管理","cells":["少量分餐、饮食组成与症状/血糖评估","减少诱发并处理低血糖","体位及营养个体化，不套所有术式"],"source":"D22:P0106–P0129、P0140–P0158、P0182–P0203","id":"gi-surgery-treatment-3"},{"topic":"造口治疗","cells":["装置适配、皮肤保护和并发症处理","恢复自主生活","坏死/回缩处理不按一个面积口诀自行定"],"source":"D22:P0106–P0129、P0140–P0158、P0182–P0203","id":"gi-surgery-treatment-4"}],"nursing":[{"topic":"胃管安全","cells":["固定、通畅、引流色质量及位置","脱出及时报告","吻合术后不盲目重新插入"],"source":"D22:P0096–P0105、P0148–P0158、P0185–P0203","id":"gi-surgery-nursing-0"},{"topic":"呼吸与疼痛","cells":["有效镇痛辅助深呼吸/咳嗽，按耐受活动","观察肺部和氧合","不能只要求忍痛排痰"],"source":"D22:P0096–P0105、P0148–P0158、P0185–P0203","id":"gi-surgery-nursing-1"},{"topic":"造口换袋六环节","cells":["揭除→清洁→测量→裁剪→贴合→密封","根据当前造口大小保护皮肤","开口大小按器具及评估，不永远同尺寸"],"source":"D22:P0096–P0105、P0148–P0158、P0185–P0203","id":"gi-surgery-nursing-2"},{"topic":"造口异常","cells":["发暗/黑变、多量出血、回缩、排出异常等","及时联系专业人员","不自行涂止血粉或扩张"],"source":"D22:P0096–P0105、P0148–P0158、P0185–P0203","id":"gi-surgery-nursing-3"},{"topic":"引流/伤口","cells":["观察量、颜色、性质、局部及全身感染","变化联系术式和临床","不把少量淡血性直接等同大出血"],"source":"D22:P0096–P0105、P0148–P0158、P0185–P0203","id":"gi-surgery-nursing-4"},{"topic":"居家能力","cells":["本人/家属会换袋、观察皮肤、处理渗漏并知道复诊","心理、自我形象与生活参与","不只发一张注意事项"],"source":"D22:P0096–P0105、P0148–P0158、P0185–P0203","id":"gi-surgery-nursing-5"}]},"orthopedics":{"diagnosis":[{"topic":"骨折局部","cells":["痛肿、功能障碍；畸形/异常活动/骨擦感等特征","结合损伤史及影像","不主动制造骨擦感来“验证”"],"source":"D23:P0003–P0033、P0117–P0155、P0183–P0195","id":"orthopedics-diagnosis-0"},{"topic":"骨筋膜室综合征","cells":["不相称加重痛、被动牵拉痛、麻木等","缺血风险，及时评估","早期脉搏可存在，不能等全套征"],"source":"D23:P0003–P0033、P0117–P0155、P0183–P0195","id":"orthopedics-diagnosis-1"},{"topic":"脂肪栓塞方向","cells":["长骨等创伤后呼吸、神经及全身表现","及时报告并评估","不凭单一低氧确诊"],"source":"D23:P0003–P0033、P0117–P0155、P0183–P0195","id":"orthopedics-diagnosis-2"},{"topic":"肱骨干下段","cells":["桡神经损伤可见垂腕等","检查感觉运动","不同骨折部位风险不同"],"source":"D23:P0003–P0033、P0117–P0155、P0183–P0195","id":"orthopedics-diagnosis-3"},{"topic":"股骨颈/股骨干","cells":["前者不愈合和缺血坏死风险；后者失血可较多","局部与全身同时看","能暂时行走不排嵌插等骨折"],"source":"D23:P0003–P0033、P0117–P0155、P0183–P0195","id":"orthopedics-diagnosis-4"},{"topic":"腰椎间盘突出","cells":["腰痛、下肢放射痛、相关感觉运动/反射改变","结合检查与影像","会阴感觉或大小便异常警惕马尾"],"source":"D23:P0003–P0033、P0117–P0155、P0183–P0195","id":"orthopedics-diagnosis-5"}],"labs":[{"topic":"X线","cells":["骨折、移位及复位固定评价","骨性结构与过程随访","特殊隐匿伤可能需进一步检查"],"source":"D23:P0003–P0033、P0084–P0093、P0190–P0199","id":"orthopedics-labs-0"},{"topic":"CT/MRI","cells":["CT看复杂骨性细节；MRI看软组织、神经/椎管等","按损伤问题选择","不统一所有骨折都做全套"],"source":"D23:P0003–P0033、P0084–P0093、P0190–P0199","id":"orthopedics-labs-1"},{"topic":"末梢神经血管","cells":["感觉、运动、肤色皮温、毛细血管回填及脉搏","固定前后及动态比较","单一脉搏正常不排筋膜室问题"],"source":"D23:P0003–P0033、P0084–P0093、P0190–P0199","id":"orthopedics-labs-2"},{"topic":"血象及全身评估","cells":["创伤失血、感染和治疗风险","关注骨盆/股骨等大出血","不能只查局部片不看休克"],"source":"D23:P0003–P0033、P0084–P0093、P0190–P0199","id":"orthopedics-labs-3"},{"topic":"直腿抬高等","cells":["放射痛及神经根相关体征","腰椎病变评估线索","体征非独立确诊，不能粗暴诱发"],"source":"D23:P0003–P0033、P0084–P0093、P0190–P0199","id":"orthopedics-labs-4"}],"treatment":[{"topic":"骨折基本路径","cells":["复位、固定、功能恢复","生命危险先处理，再保护肢体","开放伤、血管神经损伤另评估"],"source":"D23:P0038–P0058、P0083–P0106、P0200–P0202","id":"orthopedics-treatment-0"},{"topic":"固定选择","cells":["石膏、牵引或内固定等依类型稳定性","维护对位与愈合","不能人人按同一拆除日期"],"source":"D23:P0038–P0058、P0083–P0106、P0200–P0202","id":"orthopedics-treatment-1"},{"topic":"筋膜室/压迫危险","cells":["及时报告并配合减压等评估处理","防持续缺血损伤","不单纯加镇痛、按摩热敷后等"],"source":"D23:P0038–P0058、P0083–P0106、P0200–P0202","id":"orthopedics-treatment-2"},{"topic":"腰椎非手术/手术","cells":["按症状、缺损及治疗反应选择","马尾等危险需及时升级","不把讲义有效率当个体承诺"],"source":"D23:P0038–P0058、P0083–P0106、P0200–P0202","id":"orthopedics-treatment-3"},{"topic":"术后康复","cells":["负重和活动依术式、入路及恢复","恢复肌力关节与生活能力","髋置换不一律同禁忌天数"],"source":"D23:P0038–P0058、P0083–P0106、P0200–P0202","id":"orthopedics-treatment-4"}],"nursing":[{"topic":"石膏未干固","cells":["平托保护形状，避免手指局部压陷","维护固定与皮肤","保暖不造成局部灼伤"],"source":"D23:P0041–P0106、P0107–P0111","id":"orthopedics-nursing-0"},{"topic":"石膏干固后","cells":["清洁干燥，看痛、麻木、皮温肤色及渗出","异常即评估/报告","不伸异物搔痒，不自行剪改"],"source":"D23:P0041–P0106、P0107–P0111","id":"orthopedics-nursing-1"},{"topic":"牵引有效性","cells":["方向、反牵引、身体位置和重锤悬空","每日及移动后核查","不自行增减重量或松绳"],"source":"D23:P0041–P0106、P0107–P0111","id":"orthopedics-nursing-2"},{"topic":"牵引针眼/皮肤","cells":["红肿痛渗出与神经血管状态","依流程清洁维护","针移位不自行推回"],"source":"D23:P0041–P0106、P0107–P0111","id":"orthopedics-nursing-3"},{"topic":"脊柱翻身搬运","cells":["保持轴线和中立，团队协调","防继发损伤","不能一人抬头一人抬脚搂抱"],"source":"D23:P0041–P0106、P0107–P0111","id":"orthopedics-nursing-4"},{"topic":"功能锻炼","cells":["按阶段维护未固定关节、肌力和活动范围","预防失用并恢复功能","活动服从稳定、术式和负重要求"],"source":"D23:P0041–P0106、P0107–P0111","id":"orthopedics-nursing-5"},{"topic":"异常就医","cells":["痛肿加重、肢冷麻木、固定松动或感染线索","及时复诊","不等到完全不能活动才报告"],"source":"D23:P0041–P0106、P0107–P0111","id":"orthopedics-nursing-6"}]}};
